const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var southSpain = ee.Geometry.Rectangle([-7.5, 36.0, -1.5, 38.5]); // Southern Spain region
  var startDate = '2023-04-01';
  var endDate = '2023-04-30';

  // 2. Data Acquisition - MODIS Land Surface Temperature
  var modisCol = ee.ImageCollection('MODIS/061/MOD11A2')
    .filterDate(startDate, endDate)
    .filterBounds(southSpain)
    .select('LST_Day_1km');

  var colSize = modisCol.size().getInfo();
  console.log(`April 2023 MODIS images: ${colSize}`);

  if (colSize === 0) {
    console.log("No MODIS data found, trying MOD11A1...");
    modisCol = ee.ImageCollection('MODIS/061/MOD11A1')
      .filterDate(startDate, endDate)
      .filterBounds(southSpain)
      .select('LST_Day_1km');
    colSize = modisCol.size().getInfo();
    console.log(`April 2023 MOD11A1 images: ${colSize}`);
  }

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Convert LST from Kelvin to Fahrenheit
  var tempCollection = modisCol.map(function(image) {
    // Convert from Kelvin to Fahrenheit: F = (K × 9/5) - 459.67
    var tempF = image.multiply(0.02).multiply(9/5).subtract(459.67); // MODIS LST scale factor 0.02
    return tempF.rename('temp_fahrenheit');
  });

  // Get maximum temperature composite for April
  var maxTemp = tempCollection.max();

  // 4. Check for valid pixels and calculate stats
  var pixelCount = maxTemp.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: southSpain,
    scale: 1000,
    maxPixels: 1e9
  }).get('temp_fahrenheit').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Get temperature statistics
  var tempStats = maxTemp.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.max(),
      sharedInputs: true
    }),
    geometry: southSpain,
    scale: 3000,
    maxPixels: 1e9
  });

  var meanTemp = tempStats.get('temp_fahrenheit_mean').getInfo();
  var maxTempVal = tempStats.get('temp_fahrenheit_max').getInfo();

  console.log(`Mean temp: ${meanTemp?.toFixed(1)}°F`);
  console.log(`Max temp: ${maxTempVal?.toFixed(1)}°F`);

  // 5. Validation & Final Answer
  if (meanTemp === null || maxTempVal === null || 
      meanTemp === undefined || maxTempVal === undefined ||
      maxTempVal < -100 || maxTempVal > 150) { // Validate temperature range
    console.log("<answer>C3</answer>");
  } else if (maxTempVal > 90) {
    console.log(`Evidence: Maximum temperature ${maxTempVal.toFixed(1)}°F exceeds 90°F`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Evidence: Maximum temperature ${maxTempVal.toFixed(1)}°F below 90°F`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
